<main class="main"><header class="topbar"><div><p>LIVE TRACKING</p><h1>Start GPS run</h1></div><span id="gpsStatus" class="type-pill">GPS ready</span></header>
<div class="gps-layout"><section class="card gps-map-wrap"><div id="runMap"><div class="map-controls"><button type="button" id="zoomIn" title="Zoom in">+</button><button type="button" id="zoomOut" title="Zoom out">−</button><button type="button" id="locateBtn" title="Current location">⌖</button><button type="button" id="followBtn" class="follow-active" title="Live follow">◎</button></div><div id="followLabel" class="follow-label">LIVE FOLLOW ON</div></div></section><section class="gps-side"><div class="gps-live card"><small>DISTANCE</small><strong id="liveDistance">0.00</strong><em>km</em><div><small>DURATION</small><b id="liveDuration">00:00:00</b></div></div><div class="stats-grid gps-stats"><article class="card"><small>Average pace</small><strong id="livePace">0:00</strong></article><article class="card"><small>Speed</small><strong id="liveSpeed">0.0</strong></article></div><div class="gps-controls"><button id="startBtn" class="primary-button">START RUN</button><button id="pauseBtn" class="secondary-button" disabled>PAUSE</button><button id="stopBtn" class="stop-button" disabled>STOP</button></div><form id="savePanel" class="card gps-save" hidden>@csrf<select class="input" id="runType"><option>Easy Run</option><option>Long Run</option><option>Tempo Run</option><option>Interval</option><option>Race</option></select><select class="input" id="shoeId"><option value="">No shoes</option>@foreach(auth()->user()->shoes()->get() as $shoe)<option value="{{ $shoe->id }}">{{ $shoe->brand }} {{ $shoe->model }}</option>@endforeach</select><textarea class="input" id="notes" placeholder="Run notes"></textarea><button class="primary-button" type="submit">SAVE GPS RUN</button></form></section></div></main></div>
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
<script>
let map,Lpoints=[],running=false,paused=false,distance=0,duration=0,lastPoint=null,lastAltitude=null,elevationGain=0,lastCurrent=null,startPoint=null,startTime=null,timer=null,routeLine=null,currentMarker=null,startMarker=null,finishMarker=null,liveFollow=true;
map=L.map('runMap',{zoomControl:false}).setView([3.139,101.6869],13);
L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);
routeLine=L.polyline([], {color:'#b8f34a',weight:5}).addTo(map);
map.on('dragstart',()=>setFollow(false));
function haversine(a,b){let R=6371,toRad=x=>x*Math.PI/180,dl=toRad(b.lat-a.lat),doq=toRad(b.lng-a.lng),x=Math.sin(dl/2)**2+Math.cos(toRad(a.lat))*Math.cos(toRad(b.lat))*Math.sin(doq/2)**2;return R*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));}
function formatTime(s){return [Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(x=>String(x).padStart(2,'0')).join(':')}
function update(){duration++;let pace=distance?(duration/60/distance):0,mins=Math.floor(pace),secs=Math.round((pace-mins)*60);liveDuration.textContent=formatTime(duration);liveDistance.textContent=distance.toFixed(2);livePace.textContent=pace?mins+':'+String(secs).padStart(2,'0'):'0:00';liveSpeed.textContent=distance&&duration?(distance/(duration/3600)).toFixed(1):'0.0'}
function locationError(){gpsStatus.textContent='GPS unavailable';gpsStatus.style.color='#ff8b91'}
function setFollow(enabled){liveFollow=enabled;followBtn.classList.toggle('follow-active',enabled);followLabel.textContent=enabled?'LIVE FOLLOW ON':'LIVE FOLLOW OFF';if(enabled&&lastCurrent)map.setView([lastCurrent.lat,lastCurrent.lng],17)}
function gpsPosition(position){let p=position.coords,point={lat:p.latitude,lng:p.longitude};lastCurrent=point;if(currentMarker)currentMarker.setLatLng([p.latitude,p.longitude]);else currentMarker=L.circleMarker([p.latitude,p.longitude],{radius:7,color:'#fff',weight:2,fillColor:'#b8f34a',fillOpacity:1}).addTo(map);if(liveFollow)map.setView([p.latitude,p.longitude],17);gpsStatus.textContent='GPS fixed · ±'+Math.round(p.accuracy)+'m';gpsStatus.style.color='#b8f34a';return point}
function locateCurrent(){if(!navigator.geolocation)return locationError();navigator.geolocation.getCurrentPosition(position=>gpsPosition(position),locationError,{enableHighAccuracy:true,timeout:10000,maximumAge:5000})}
function track(position){let p=position.coords;if(p.accuracy>25)return;let point=gpsPosition(position);if(!running||paused)return;let altitude=p.altitude;if(altitude!=null&&lastAltitude!=null&&altitude>lastAltitude)elevationGain+=Math.min(altitude-lastAltitude,20);if(altitude!=null)lastAltitude=altitude;if(lastPoint){let gap=haversine(lastPoint,point);if(gap<0.003)return;let timeGap=(position.timestamp-lastPoint.timestamp)/1000;let speed=timeGap>0?gap/(timeGap/3600):0;if(gap>.2||speed>45)return;distance+=gap}let recorded={...point,accuracy:p.accuracy,altitude,recorded_at:new Date(position.timestamp).toISOString(),timestamp:position.timestamp};lastPoint=recorded;Lpoints.push(recorded);routeLine.addLatLng([point.lat,point.lng]);if(finishMarker)finishMarker.setLatLng([point.lat,point.lng])}
locateCurrent();navigator.geolocation.watchPosition(track,locationError,{enableHighAccuracy:true,maximumAge:1000,timeout:10000});
zoomIn.onclick=()=>map.zoomIn();zoomOut.onclick=()=>map.zoomOut();locateBtn.onclick=()=>{locateCurrent();setFollow(true)};followBtn.onclick=()=>setFollow(!liveFollow);
startBtn.onclick=()=>{if(!navigator.geolocation)return locationError();running=true;paused=false;startBtn.disabled=true;pauseBtn.disabled=false;stopBtn.disabled=false;startTime=new Date();duration=0;distance=0;elevationGain=0;lastAltitude=null;Lpoints=[];lastPoint=null;routeLine.setLatLngs([]);if(lastCurrent){startPoint={...lastCurrent};startMarker=L.circleMarker([startPoint.lat,startPoint.lng],{radius:7,color:'#fff',weight:2,fillColor:'#b8f34a',fillOpacity:1}).addTo(map)}timer=setInterval(()=>{if(!paused)update()},1000)};
pauseBtn.onclick=()=>{paused=!paused;pauseBtn.textContent=paused?'RESUME':'PAUSE';gpsStatus.textContent=paused?'RUN PAUSED':'GPS live';gpsStatus.style.color=paused?'#f5c77b':'#b8f34a'};
stopBtn.onclick=()=>{if(!confirm('Stop and save this run?'))return;running=false;clearInterval(timer);startBtn.disabled=false;pauseBtn.disabled=true;stopBtn.disabled=true;pauseBtn.textContent='PAUSE';if(lastCurrent)finishMarker=L.circleMarker([lastCurrent.lat,lastCurrent.lng],{radius:7,color:'#fff',weight:2,fillColor:'#ff8b91',fillOpacity:1}).addTo(map);savePanel.hidden=false;savePanel.scrollIntoView({behavior:'smooth'})};
savePanel.onsubmit=async e=>{e.preventDefault();let res=await fetch('{{ route('gps.save') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'},body:JSON.stringify({distance_km:distance,duration_seconds:duration,run_type:runType.value,shoe_id:shoeId.value||null,notes:notes.value,started_at:startTime?.toISOString(),elevation_gain_m:elevationGain,points:Lpoints})});let data=await res.json();if(res.ok&&data.ok){location.href='{{ route('runs.index') }}'}else{alert(data.message||'Unable to save run')}};
</script>@endsection
